using namespace std;

int main() {
    int width, p;
    cin >> width >> p;
    string border(width + 4, '*');
    vector<string> out = {border};
    for (int k = 0; k < p; k++) {
        int count;
        cin >> count;
        vector<string> words(count);
        for (auto &w : words) cin >> w;
        int start = 0;
        while (start < count) {
            // Greedily take as many words as fit with single spaces.
            int end = start, letters = 0;
            while (end < count && letters + (int)words[end].size() + end - start <= width) letters += words[end++].size();
            int cnt = end - start;
            string content;
            if (end == count || cnt == 1) {
                // Last line of a paragraph or a single word: center, extra space on the right.
                string line = words[start];
                for (int i = start + 1; i < end; i++) line += " " + words[i];
                int padding = width - line.size(), left = padding / 2;
                content = string(left, ' ') + line + string(padding - left, ' ');
            } else {
                // Full justification: spread spaces evenly, leftmost gaps get the remainder.
                int gaps = cnt - 1, base = (width - letters) / gaps, extra = (width - letters) % gaps;
                for (int i = 0; i < cnt; i++) {
                    content += words[start + i];
                    if (i < gaps) content += string(base + (i < extra), ' ');
                }
            }
            out.push_back("* " + content + " *");
            start = end;
        }
    }
    out.push_back(border);
    for (auto &s : out) cout << s << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int width = nextInt(), p = nextInt();
        String border = "*".repeat(width + 4);
        StringBuilder sb = new StringBuilder(border).append('\n');
        for (int k = 0; k < p; k++) {
            int count = nextInt();
            String[] words = new String[count];
            for (int i = 0; i < count; i++) words[i] = next();
            int start = 0;
            while (start < count) {
                // Greedily take as many words as fit with single spaces.
                int end = start, letters = 0;
                while (end < count && letters + words[end].length() + end - start <= width) letters += words[end++].length();
                int cnt = end - start;
                StringBuilder content = new StringBuilder();
                if (end == count || cnt == 1) {
                    // Last line of a paragraph or a single word: center, extra space on the right.
                    String line = String.join(" ", java.util.Arrays.copyOfRange(words, start, end));
                    int padding = width - line.length(), left = padding / 2;
                    content.append(" ".repeat(left)).append(line).append(" ".repeat(padding - left));
                } else {
                    // Full justification: spread spaces evenly, leftmost gaps get the remainder.
                    int gaps = cnt - 1, base = (width - letters) / gaps, extra = (width - letters) % gaps;
                    for (int i = 0; i < cnt; i++) {
                        content.append(words[start + i]);
                        if (i < gaps) content.append(" ".repeat(base + (i < extra ? 1 : 0)));
                    }
                }
                sb.append("* ").append(content).append(" *\n");
                start = end;
            }
        }
        sb.append(border).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strings"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	width, p := readInt(), readInt()
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	border := strings.Repeat("*", width+4)
	w.WriteString(border + "\n")
	for k := 0; k < p; k++ {
		count := readInt()
		words := make([]string, count)
		for i := range words {
			words[i] = readToken()
		}
		for start := 0; start < count; {
			// Greedily take as many words as fit with single spaces.
			end, letters := start, 0
			for end < count && letters+len(words[end])+end-start <= width {
				letters += len(words[end])
				end++
			}
			cnt := end - start
			var content string
			if end == count || cnt == 1 {
				// Last line of a paragraph or a single word: center, extra space on the right.
				line := strings.Join(words[start:end], " ")
				padding := width - len(line)
				left := padding / 2
				content = strings.Repeat(" ", left) + line + strings.Repeat(" ", padding-left)
			} else {
				// Full justification: spread spaces evenly, leftmost gaps get the remainder.
				gaps := cnt - 1
				base, extra := (width-letters)/gaps, (width-letters)%gaps
				var b strings.Builder
				for i := 0; i < cnt; i++ {
					b.WriteString(words[start+i])
					if i < gaps {
						s := base
						if i < extra {
							s++
						}
						b.WriteString(strings.Repeat(" ", s))
					}
				}
				content = b.String()
			}
			w.WriteString("* " + content + " *\n")
			start = end
		}
	}
	w.WriteString(border + "\n")
}
